// Leads del nodo actual
const leads = $input.first().json.response || [];

// Filas del SQL
const sqlRows = $("Execute a SQL query1").all().map(item => item.json || {});

// Set de LeadId permitidos
const leadIdsPermitidos = new Set(
  sqlRows
    .map(row => String(row.LeadId || '').trim())
    .filter(Boolean)
);

// Filtrar + enriquecer
const leadsValidos = leads
  .filter(lead => {
    const leadId = String(lead.ID_LEAD || '').trim();
    return leadIdsPermitidos.has(leadId);
  })
  .map(lead => {
    const leadNormalizado = normalizePhone({ ...lead });

    const businesstypeid = getBusinessTypeId(leadNormalizado.TIPO_DE_REGISTRO_DE_LEAD);
    const dealerEmail = findDealerEmail(leadNormalizado.CODIGO_DEL_DEALER);
    const pilotCode = findPilotCode(
      leadNormalizado.ORIGEN_DEL_LEAD,
      leadNormalizado.SUB_ORIGEN,
      leadNormalizado.DETALLE,
      leadNormalizado.SUBDETALLE
    );

    return {
      ...leadNormalizado,
      businesstypeid,
      dealerEmail,
      pilotCode
    };
  });

return leadsValidos;
